schemaSql:
-- PostgreSQL Schema for "المدرار للمقاولات الهندسية" (Al-Madrar Engineering Contracting)

-- 0. Helper function for admin checks
create or replace function public.almadrar_is_admin()
returns boolean as $$
begin
    return (
        current_setting('request.jwt.claim.role', true) = 'service_role'
        or coalesce(auth.jwt() -> 'user_metadata' ->> 'is_admin', 'false') = 'true'
        or coalesce(auth.jwt() -> 'app_metadata' ->> 'role', '') = 'admin'
    );
end;
$$ language plpgsql security definer;

-- 1. Table: almadrar_otp_verifications (Email OTP & Account Confirmations)
create table if not exists public.almadrar_otp_verifications (
    id bigint generated always as identity primary key,
    email text not null,
    otp_code text not null,
    purpose text default 'verification',
    is_used boolean default false,
    expires_at timestamptz not null,
    created_at timestamptz default now()
);

alter table public.almadrar_otp_verifications add column if not exists email text;
alter table public.almadrar_otp_verifications add column if not exists otp_code text;
alter table public.almadrar_otp_verifications add column if not exists purpose text default 'verification';
alter table public.almadrar_otp_verifications add column if not exists is_used boolean default false;
alter table public.almadrar_otp_verifications add column if not exists expires_at timestamptz;
alter table public.almadrar_otp_verifications add column if not exists created_at timestamptz default now();

alter table public.almadrar_otp_verifications enable row level security;

drop policy if exists "Authenticated users and admins can view OTPs" on public.almadrar_otp_verifications;
create policy "Authenticated users and admins can view OTPs"
    on public.almadrar_otp_verifications for select to authenticated
    using (email = auth.jwt()->>'email' or public.almadrar_is_admin());

drop policy if exists "Authenticated users can create OTP entries" on public.almadrar_otp_verifications;
create policy "Authenticated users can create OTP entries"
    on public.almadrar_otp_verifications for insert to authenticated
    with check (true);

drop policy if exists "Users and admins can update OTPs" on public.almadrar_otp_verifications;
create policy "Users and admins can update OTPs"
    on public.almadrar_otp_verifications for update to authenticated
    using (email = auth.jwt()->>'email' or public.almadrar_is_admin());


-- 2. Table: almadrar_services (Engineering & Construction Services Catalog)
create table if not exists public.almadrar_services (
    id bigint generated always as identity primary key,
    title text not null,
    category text not null,
    description text,
    image_url text,
    workflow_steps jsonb default '[]'::jsonb,
    display_order integer default 0,
    created_at timestamptz default now()
);

alter table public.almadrar_services add column if not exists title text;
alter table public.almadrar_services add column if not exists category text;
alter table public.almadrar_services add column if not exists description text;
alter table public.almadrar_services add column if not exists image_url text;
alter table public.almadrar_services add column if not exists workflow_steps jsonb default '[]'::jsonb;
alter table public.almadrar_services add column if not exists display_order integer default 0;
alter table public.almadrar_services add column if not exists created_at timestamptz default now();

alter table public.almadrar_services enable row level security;

drop policy if exists "Authenticated users can view services" on public.almadrar_services;
create policy "Authenticated users can view services"
    on public.almadrar_services for select to authenticated
    using (true);

drop policy if exists "Admins can manage services" on public.almadrar_services;
create policy "Admins can manage services"
    on public.almadrar_services for all to authenticated
    using (public.almadrar_is_admin())
    with check (public.almadrar_is_admin());


-- 3. Table: almadrar_projects (Customer Contracting Requests & Executed Projects)
create table if not exists public.almadrar_projects (
    id bigint generated always as identity primary key,
    request_code text,
    customer_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
    service_type text not null,
    approximate_area numeric(10,2),
    location_details text not null,
    attachments jsonb default '[]'::jsonb,
    notes text,
    status text not null default 'pending_inspection',
    estimated_cost numeric(12,2),
    cost_breakdown_notes text,
    estimated_duration text,
    expected_start_date date,
    customer_accepted boolean default false,
    progress_percentage integer default 0,
    current_stage text,
    created_at timestamptz default now()
);

alter table public.almadrar_projects add column if not exists request_code text;
alter table public.almadrar_projects add column if not exists customer_id uuid default auth.uid();
alter table public.almadrar_projects add column if not exists service_type text;
alter table public.almadrar_projects add column if not exists approximate_area numeric(10,2);
alter table public.almadrar_projects add column if not exists location_details text;
alter table public.almadrar_projects add column if not exists attachments jsonb default '[]'::jsonb;
alter table public.almadrar_projects add column if not exists notes text;
alter table public.almadrar_projects add column if not exists status text default 'pending_inspection';
alter table public.almadrar_projects add column if not exists estimated_cost numeric(12,2);
alter table public.almadrar_projects add column if not exists cost_breakdown_notes text;
alter table public.almadrar_projects add column if not exists estimated_duration text;
alter table public.almadrar_projects add column if not exists expected_start_date date;
alter table public.almadrar_projects add column if not exists customer_accepted boolean default false;
alter table public.almadrar_projects add column if not exists progress_percentage integer default 0;
alter table public.almadrar_projects add column if not exists current_stage text;
alter table public.almadrar_projects add column if not exists created_at timestamptz default now();

alter table public.almadrar_projects enable row level security;

drop policy if exists "Customers and admins can view projects" on public.almadrar_projects;
create policy "Customers and admins can view projects"
    on public.almadrar_projects for select to authenticated
    using (customer_id = auth.uid() or public.almadrar_is_admin());

drop policy if exists "Customers and admins can insert projects" on public.almadrar_projects;
create policy "Customers and admins can insert projects"
    on public.almadrar_projects for insert to authenticated
    with check (customer_id = auth.uid() or public.almadrar_is_admin());

drop policy if exists "Customers and admins can update projects" on public.almadrar_projects;
create policy "Customers and admins can update projects"
    on public.almadrar_projects for update to authenticated
    using (customer_id = auth.uid() or public.almadrar_is_admin());

drop policy if exists "Admins can delete projects" on public.almadrar_projects;
create policy "Admins can delete projects"
    on public.almadrar_projects for delete to authenticated
    using (public.almadrar_is_admin());


-- 4. Table: almadrar_project_updates (Field Inspection & Stage Progress Reports)
create table if not exists public.almadrar_project_updates (
    id bigint generated always as identity primary key,
    project_id bigint not null references public.almadrar_projects(id) on delete cascade,
    customer_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
    stage_title text not null,
    progress_percentage integer not null default 0,
    engineer_notes text,
    images jsonb default '[]'::jsonb,
    created_at timestamptz default now()
);

alter table public.almadrar_project_updates add column if not exists project_id bigint;
alter table public.almadrar_project_updates add column if not exists customer_id uuid default auth.uid();
alter table public.almadrar_project_updates add column if not exists stage_title text;
alter table public.almadrar_project_updates add column if not exists progress_percentage integer default 0;
alter table public.almadrar_project_updates add column if not exists engineer_notes text;
alter table public.almadrar_project_updates add column if not exists images jsonb default '[]'::jsonb;
alter table public.almadrar_project_updates add column if not exists created_at timestamptz default now();

alter table public.almadrar_project_updates enable row level security;

drop policy if exists "Customers and admins can view project updates" on public.almadrar_project_updates;
create policy "Customers and admins can view project updates"
    on public.almadrar_project_updates for select to authenticated
    using (customer_id = auth.uid() or public.almadrar_is_admin());

drop policy if exists "Admins can insert and manage project updates" on public.almadrar_project_updates;
create policy "Admins can insert and manage project updates"
    on public.almadrar_project_updates for all to authenticated
    using (public.almadrar_is_admin())
    with check (public.almadrar_is_admin());


-- 5. Table: almadrar_portfolio (Company Work Showcase / Previous Projects)
create table if not exists public.almadrar_portfolio (
    id bigint generated always as identity primary key,
    title text not null,
    description text,
    category text not null,
    location text,
    images jsonb default '[]'::jsonb,
    videos jsonb default '[]'::jsonb,
    created_at timestamptz default now()
);

alter table public.almadrar_portfolio add column if not exists title text;
alter table public.almadrar_portfolio add column if not exists description text;
alter table public.almadrar_portfolio add column if not exists category text;
alter table public.almadrar_portfolio add column if not exists location text;
alter table public.almadrar_portfolio add column if not exists images jsonb default '[]'::jsonb;
alter table public.almadrar_portfolio add column if not exists videos jsonb default '[]'::jsonb;
alter table public.almadrar_portfolio add column if not exists created_at timestamptz default now();

alter table public.almadrar_portfolio enable row level security;

drop policy if exists "Authenticated users can read portfolio items" on public.almadrar_portfolio;
create policy "Authenticated users can read portfolio items"
    on public.almadrar_portfolio for select to authenticated
    using (true);

drop policy if exists "Admins can manage portfolio items" on public.almadrar_portfolio;
create policy "Admins can manage portfolio items"
    on public.almadrar_portfolio for all to authenticated
    using (public.almadrar_is_admin())
    with check (public.almadrar_is_admin());


